#!/usr/bin/env python3
"""Pin the published error-code contract against its runtime source.

``app.core.exceptions`` emits a stable ``error.code`` for every API error.
Two things can drift without any existing gate noticing:

* ``http_exception_handler`` falls back to ``http_error`` for a generic
  ``HTTPException`` (400/413/500/503, ...), but that code has no
  ``SoyMutDBError`` subclass. A catalog built only from the exception
  hierarchy therefore omits a code clients can actually receive.
* ``packages/api-client/error-codes.json`` is regenerated by
  ``generate:api-client`` but never checked by ``check-contract.sh``; a
  hand edit, or a stale generation, leaves the two published catalogs
  disagreeing with no red gate.

This guard reads committed bytes only (no API venv, no export), so reverting
the backend, the snapshot and the generated client together cannot co-revert
it. It complements ``check-contract.sh``, which owns export/snapshot/client
byte equality.
"""
from __future__ import annotations

import argparse
import ast
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SNAPSHOT = ROOT / "packages/api-client/openapi.json"
CODES = ROOT / "packages/api-client/error-codes.json"
SOURCE = ROOT / "apps/api/app/core/exceptions.py"

FALLBACK_CODE = "http_error"

#: The exact source line that publishes the fallback code in the catalog.
#: Held as one constant so the guard, its self-test and the wiring test all
#: assert against the same text instead of three drifting copies.
_FALLBACK_CATALOG_ENTRY = (
    "    catalog[HTTP_ERROR_CODE] = (\n"
    '        "Generic HTTPException fallback; see x-error-status for the statuses that use it."\n'
    "    )\n"
)

HTTP_STATUS_CODES = {
    "401": "authentication_failed",
    "403": "forbidden",
    "404": "not_found",
}


def _source_error_codes(source: str) -> set[str]:
    """Collect every emitted ``error.code`` literal from the source.

    Covers both the ``error_code``/``code`` assignments inside exception
    classes/handlers and the module-level ``HTTP_ERROR_CODE`` fallback
    constant, so a co-revert that renames the fallback cannot pass.

    A literal scan alone is too weak: dropping the ``catalog[HTTP_ERROR_CODE]``
    assignment leaves the constant in place, so ``http_error`` still appears in
    the literal set and the *only* gate that notices is the 3.15 export diff.
    ``check`` therefore additionally evaluates the source tree and compares the
    real ``error_code_catalog()`` output, which is the function the published
    snapshot is actually generated from.
    """
    tree = ast.parse(source)
    found: set[str] = set()
    for node in ast.walk(tree):
        if not isinstance(node, (ast.Assign, ast.AnnAssign)):
            continue
        targets = node.targets if isinstance(node, ast.Assign) else [node.target]
        value = node.value
        if not isinstance(value, ast.Constant) or not isinstance(value.value, str):
            continue
        for target in targets:
            if isinstance(target, ast.Name) and target.id in {
                "error_code",
                "code",
                "HTTP_ERROR_CODE",
            }:
                found.add(value.value)
    return found


def _executed_catalog(source: Path) -> tuple[dict[str, str] | None, str | None]:
    """Import the module and return the catalog it really builds.

    The literal scan in :func:`_source_error_codes` answers "is this string
    mentioned anywhere?", which a leftover ``HTTP_ERROR_CODE = "http_error"``
    keeps answering yes to after the catalog entry itself was deleted. This
    runs ``error_code_catalog()`` -- the function the published ``x-error-codes``
    is generated from -- so the guard pins behaviour, not vocabulary.

    ``app.core.exceptions`` imports FastAPI/Starlette, which the guard must not
    require (it runs before the export, on hosts with no API venv). The module
    is therefore executed in isolation: its imports are stubbed and only the
    catalog function is called.
    """
    import types

    tree = ast.parse(source.read_text(encoding="utf-8"))

    # Collect the module-level names the catalog function closes over: the
    # exception hierarchy, ``_iter_error_types`` and the fallback constant.
    keep_functions = {"_iter_error_types", "error_code_catalog"}
    keep_assigns = {"HTTP_ERROR_CODE", "UNPROCESSABLE_STATUS"}
    body: list[ast.stmt] = []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name in keep_functions:
            body.append(node)
        elif isinstance(node, ast.ClassDef):
            body.append(node)
        elif isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            names = {t.id for t in targets if isinstance(t, ast.Name)}
            if names & keep_assigns:
                if names & {"UNPROCESSABLE_STATUS"}:
                    node = ast.Assign(
                        targets=list(targets),
                        value=ast.Constant(value=422),
                    )
                    ast.fix_missing_locations(node)
                body.append(node)
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            if module.startswith("__future__"):
                body.append(node)

    if not any(isinstance(n, ast.FunctionDef) and n.name == "error_code_catalog" for n in body):
        return None, "source has no error_code_catalog() to verify"

    module = ast.Module(body=body, type_ignores=[])
    namespace: dict[str, object] = {"status": types.SimpleNamespace(**{
        "HTTP_500_INTERNAL_SERVER_ERROR": 500,
        "HTTP_401_UNAUTHORIZED": 401,
        "HTTP_403_FORBIDDEN": 403,
        "HTTP_404_NOT_FOUND": 404,
        "HTTP_409_CONFLICT": 409,
        "HTTP_429_TOO_MANY_REQUESTS": 429,
        "HTTP_503_SERVICE_UNAVAILABLE": 503,
    })}
    try:
        exec(compile(module, str(source), "exec"), namespace)  # noqa: S102
        catalog = namespace["error_code_catalog"]()
    except Exception as exc:  # pragma: no cover - reported, not raised
        return None, f"could not evaluate error_code_catalog(): {exc}"
    if not isinstance(catalog, dict):
        return None, "error_code_catalog() did not return a dict"
    return {str(k): str(v) for k, v in catalog.items()}, None


def check(snapshot: Path, codes: Path, source: Path) -> list[str]:
    failures: list[str] = []

    document = json.loads(snapshot.read_text(encoding="utf-8"))
    catalog = document.get("x-error-codes")
    status = document.get("x-error-status")
    published_codes = json.loads(codes.read_text(encoding="utf-8"))
    src = source.read_text(encoding="utf-8")

    if not isinstance(catalog, dict):
        return ["openapi.json has no x-error-codes catalog"]
    if not isinstance(status, dict):
        return ["openapi.json has no x-error-status binding"]

    if published_codes != catalog:
        failures.append(
            "packages/api-client/error-codes.json disagrees with "
            "openapi.json x-error-codes (regenerate with generate:api-client)"
        )

    emitted = _source_error_codes(src)
    missing = sorted(emitted - set(catalog))
    if missing:
        failures.append(f"x-error-codes omits codes emitted at runtime: {missing}")
    if FALLBACK_CODE not in emitted:
        failures.append(
            f"runtime source no longer emits the '{FALLBACK_CODE}' fallback "
            "(HTTP_ERROR_CODE was renamed or removed)"
        )
    if FALLBACK_CODE not in catalog:
        failures.append(
            f"x-error-codes omits the generic HTTPException fallback '{FALLBACK_CODE}'"
        )

    # The literal scan above is satisfied by the bare ``HTTP_ERROR_CODE``
    # constant even when ``error_code_catalog()`` stops publishing it, so pin
    # the executed function too. Without this, deleting the one
    # ``catalog[HTTP_ERROR_CODE] = ...`` assignment leaves every stdlib gate
    # green and only the 3.15 export diff (which needs an API venv) notices.
    executed, why = _executed_catalog(source)
    if executed is None:
        failures.append(f"cannot verify the emitted catalog: {why}")
    else:
        unpublished = sorted(set(executed) - set(catalog))
        if unpublished:
            failures.append(
                "x-error-codes omits codes emitted by error_code_catalog(): "
                f"{unpublished}"
            )
        phantom = sorted(set(catalog) - set(executed))
        if phantom:
            failures.append(
                "x-error-codes publishes codes error_code_catalog() never emits: "
                f"{phantom}"
            )

    by_code = status.get("by_code")
    http_exception = status.get("http_exception")
    if not isinstance(by_code, dict) or not isinstance(http_exception, dict):
        failures.append("x-error-status must carry by_code and http_exception maps")
    else:
        if set(by_code) != set(catalog):
            failures.append(
                "x-error-status.by_code keys disagree with x-error-codes "
                f"(missing={sorted(set(catalog) - set(by_code))}, "
                f"extra={sorted(set(by_code) - set(catalog))})"
            )
        if by_code.get(FALLBACK_CODE) is not None:
            failures.append(
                f"x-error-status.by_code['{FALLBACK_CODE}'] must be null "
                "(it is the multi-status fallback, not one status)"
            )
        if http_exception.get("fallback") != FALLBACK_CODE:
            failures.append(
                f"x-error-status.http_exception.fallback must be '{FALLBACK_CODE}'"
            )
        for code, expected in HTTP_STATUS_CODES.items():
            if http_exception.get(code) != expected:
                failures.append(
                    f"x-error-status.http_exception[{code}] must be '{expected}'"
                )

    return failures


def self_test() -> int:
    """Prove each negative shape is rejected, on a copied tree."""
    import tempfile

    base = json.loads(SNAPSHOT.read_text(encoding="utf-8"))
    codes = json.loads(CODES.read_text(encoding="utf-8"))
    src = SOURCE.read_text(encoding="utf-8")
    cases: list[tuple[str, dict, dict, str]] = []

    doc = json.loads(json.dumps(base))
    doc["x-error-codes"].pop(FALLBACK_CODE)
    cases.append(("drop http_error from catalog", doc, dict(codes), src))

    doc = json.loads(json.dumps(base))
    stale_codes = {k: v for k, v in codes.items() if k != FALLBACK_CODE}
    cases.append(("stale error-codes.json", doc, stale_codes, src))

    doc = json.loads(json.dumps(base))
    del doc["x-error-status"]
    cases.append(("drop x-error-status entirely", doc, dict(codes), src))

    doc = json.loads(json.dumps(base))
    doc["x-error-status"]["by_code"][FALLBACK_CODE] = 400
    cases.append(("fallback pinned to a single status", doc, dict(codes), src))

    doc = json.loads(json.dumps(base))
    doc["x-error-status"]["http_exception"]["404"] = "gone"
    cases.append(("404 mapped to wrong code", doc, dict(codes), src))

    doc = json.loads(json.dumps(base))
    doc["x-error-status"]["by_code"].pop("conflict")
    cases.append(("by_code loses a published code", doc, dict(codes), src))

    doc = json.loads(json.dumps(base))
    doc["x-error-status"]["http_exception"].pop("fallback")
    cases.append(("http_exception loses fallback", doc, dict(codes), src))
    cases.append(
        (
            "runtime fallback constant renamed (co-revert)",
            json.loads(json.dumps(base)),
            dict(codes),
            src.replace('HTTP_ERROR_CODE = "http_error"', 'HTTP_ERROR_CODE = "http_err"'),
        )
    )
    # The constant survives here, so only running the real catalog catches it:
    # the published snapshot still lists http_error while the function stopped
    # returning it. A literal scan alone reports this tree as clean.
    dropped_catalog_entry = src.replace(_FALLBACK_CATALOG_ENTRY, "")
    assert dropped_catalog_entry != src, "self-test fixture no longer matches the source"
    cases.append(
        (
            "catalog stops emitting the fallback while the constant remains",
            json.loads(json.dumps(base)),
            dict(codes),
            dropped_catalog_entry,
        )
    )

    ok = 0
    with tempfile.TemporaryDirectory() as tmp:
        snap = Path(tmp) / "openapi.json"
        code_path = Path(tmp) / "error-codes.json"
        source_path = Path(tmp) / "exceptions.py"
        for name, doc, code_map, source_text in cases:
            snap.write_text(json.dumps(doc, indent=2), encoding="utf-8")
            code_path.write_text(
                json.dumps(code_map, indent=2, sort_keys=True) + "\n", encoding="utf-8"
            )
            source_path.write_text(source_text, encoding="utf-8")
            failures = check(snap, code_path, source_path)
            if failures:
                ok += 1
            else:
                print(f"  self-test NOT REJECTED: {name}", file=sys.stderr)
    if ok != len(cases):
        print(f"error-code contract self-test: {ok}/{len(cases)} rejected", file=sys.stderr)
        return 1
    print(f"error-code contract self-test passed ({ok} negative cases)")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--snapshot-path", type=Path, default=SNAPSHOT)
    parser.add_argument("--codes-path", type=Path, default=CODES)
    parser.add_argument("--source-path", type=Path, default=SOURCE)
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()

    if args.self_test:
        return self_test()

    failures = check(args.snapshot_path, args.codes_path, args.source_path)
    if failures:
        print("error-code contract failed:", file=sys.stderr)
        for failure in failures:
            print(f"  - {failure}", file=sys.stderr)
        return 1
    document = json.loads(args.snapshot_path.read_text(encoding="utf-8"))
    print(f"error-code contract passed ({len(document['x-error-codes'])} codes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
